def enc(x):return prior.enc(x)
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(Path(p).read_text())
def rows(p):return [json.loads(l) for l in Path(p).read_text().splitlines() if l.strip()]
def rel(p):return Path(p).relative_to(ROOT).as_posix()
def save(n,x):(OUT/n).write_bytes(enc(x))
def prepare():
 prior.prepare();ALLOWED.update(prior.ALLOWED);ALLOWED.update(p.resolve() for p in G.iterdir() if p.is_file())
def guard(event,args):
 if event!='open' or not isinstance(args[0],(str,bytes,os.PathLike)):return
 p=Path(os.fsdecode(args[0])).resolve()
 if not p.is_relative_to(ROOT):return
 writing=any(c in (args[1] or '') for c in 'wax+') or bool((args[2] or 0)&(os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC))
 if writing and not p.is_relative_to(OUT):raise PermissionError('Protected parent write')
 code=any(p.is_relative_to(ROOT/n) for n in ['src','tests']) and p.suffix in ['.py','.pyc']
 if not (p.is_relative_to(OUT) or p in ALLOWED or code or p.is_relative_to(ROOT/'.venv') or p.name in ['.gitignore','pyproject.toml'] and p.parent==ROOT):raise PermissionError('Design-only read boundary')
 if not writing:READS.add(rel(p))
def snapshot():
 x=prior.snapshot();x.update({rel(p):sha(p) for p in G.iterdir() if p.is_file()});return x

EXACT=['same_project','same_row','same_commit','same_partition_population','same_algorithm','same_modality','same_base_predictor','same_preprocessing','same_probability_input','same_fusion','calibration_link_exact']
def continuity(evidence,level='local'):
 if all(evidence.get(k) is True for k in EXACT) and (level=='local' or all(evidence.get(k) is True for k in ['adequate_projects','adequate_families','no_subset_bias','direction_stability_verified'])):return 'DIRECT'
 if level=='global' and all(evidence.get(k) is True for k in ['proven_nested_population','adequate_projects','adequate_families','no_subset_bias','direction_stability_verified','same_project','same_partition','same_algorithm','same_modality','same_preprocessing','same_base_predictor','same_probability_input','same_fusion','calibration_link_exact']):return 'NESTED'
 if evidence.get('same_architecture') is True and evidence.get('same_modality_definitions') is True:return 'ARCHITECTURAL'
 if evidence.get('same_algorithm') is True and evidence.get('same_modality') is True:return 'CONCEPTUAL_ONLY'
 return 'NONE'

def direct_record_valid(record,evidence):
 required=['project','row_identity','commit_identity','partition','algorithm_family','modality','e1_predictor_identity','e1_preprocessing_identity','modality_probability_identity','e2_base_predictor_identity','e2_meta_model_identity','calibration_identity']
 return all(isinstance(record.get(k),str) and bool(record[k]) for k in required) and record['e1_predictor_identity']==record['e2_base_predictor_identity'] and continuity(evidence,'local')=='DIRECT'

